public java.util.List<java.util.List<Integer>> separate(int[] nums) {
    java.util.List<Integer> even = new java.util.ArrayList<>();
    java.util.List<Integer> odd = new java.util.ArrayList<>();
    for (int x : nums) {
        if (x % 2 == 0) even.add(x);
        else odd.add(x);
    }
    return java.util.List.of(even, odd);
}
